import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, uv, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, Color, DirectionalLight } = THREE;

  const root = new Group();
  let mainTimeline = null;

  // Palette
  const palette = {
    background: config.colors?.background || '#0b0b10',
    surface: config.colors?.surface || '#16161d',
    paper: config.colors?.paper || '#e8ecf2',
    accent: config.colors?.accent || '#ff2a38',
    gradTop: config.colors?.gradientStops?.[0]?.hex || '#191921',
    gradBot: config.colors?.gradientStops?.[1]?.hex || '#121218',
    border: '#26262f'
  };

  // Constants
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const PADDING = 0.375;
  const ICON_R = 0.2;
  const ICON_Z = 0.05;
  const GAP_ICON = 0.25;
  const GAP_TITLE = 0.125;

  // Card data
  const cardsData = [
    {
      icon: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.'
    },
    {
      icon: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.'
    },
    {
      icon: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.'
    }
  ];

  const cardXs = [-2.5, -1.0, 0.5];

  // TSL gradient material
  const makeCardMat = () => {
    const c0 = color(new Color(palette.gradTop));
    const c1 = color(new Color(palette.gradBot));
    const grad = mix(c1, c0, uv().y);
    return new MeshStandardNodeMaterial({
      colorNode: grad,
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      transparent: true
    });
  };

  const cardGroups = [];

  // Build each card
  cardsData.forEach((data, idx) => {
    const cardGroup = new Group();
    cardGroup.position.x = cardXs[idx];
    cardGroups.push(cardGroup);

    // Card surface
    const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
    const cardMat = makeCardMat();
    const cardMesh = new Mesh(cardGeo, cardMat);
    cardMesh.position.z = 0.05;
    cardGroup.add(cardMesh);

    // Border
    const borderGeo = new PlaneGeometry(CARD_W + 0.015, CARD_H + 0.015);
    const borderMat = new MeshBasicNodeMaterial({ color: palette.border });
    const borderMesh = new Mesh(borderGeo, borderMat);
    borderMesh.position.z = 0.04;
    cardGroup.add(borderMesh);

    // Icon disc (flat in XZ plane)
    const discGeo = new CylinderGeometry(ICON_R, ICON_R, ICON_Z, 32);
    const discMat = new MeshStandardNodeMaterial({
      color: palette.surface,
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2
    });
    discMat.anisotropy = 0.6;
    const discMesh = new Mesh(discGeo, discMat);
    const iconY = CARD_H / 2 - PADDING - ICON_R;
    discMesh.position.y = iconY;
    discMesh.position.z = 0.1;
    discMesh.rotation.x = Math.PI / 2;
    cardGroup.add(discMesh);

    // Icon glyph (emissive)
    const glyph = ctx.fontAtlas.createText(data.icon, {
      fontSize: 20,
      color: palette.accent,
      align: 'center'
    });
    glyph.position.y = iconY;
    glyph.position.z = 0.14;
    glyph.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material.emissive = new Color(palette.accent);
        child.material.emissiveIntensity = 1.6;
        child.material.transparent = true;
      }
    });
    cardGroup.add(glyph);

    // Title
    const title = ctx.fontAtlas.createText(data.title, {
      fontSize: 20,
      color: palette.paper,
      align: 'center',
      maxWidthPx: 135
    });
    const titleY = iconY - ICON_R - GAP_ICON;
    title.position.y = titleY;
    title.position.z = 0.1;
    title.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material.transparent = true;
      }
    });
    cardGroup.add(title);

    // Body
    const body = ctx.fontAtlas.createText(data.body, {
      fontSize: 13,
      color: palette.paper,
      align: 'center',
      maxWidthPx: 135
    });
    const bodyY = titleY - GAP_TITLE - 0.3;
    body.position.y = bodyY;
    body.position.z = 0.1;
    body.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material.transparent = true;
      }
    });
    cardGroup.add(body);

    // Contact shadow
    const shadowGeo = new PlaneGeometry(1.65, 0.85);
    const shadowMat = new MeshBasicNodeMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.5,
      depthWrite: false
    });
    const shadowMesh = new Mesh(shadowGeo, shadowMat);
    shadowMesh.position.y = -CARD_H / 2 - 0.25;
    shadowMesh.position.z = -0.1;
    cardGroup.add(shadowMesh);

    // Hover state & handlers
    cardMesh.userData = {
      cardGroup,
      glyph,
      shadow: shadowMesh,
      hovering: false
    };

    cardMesh.userData.handlers = {
      mouseenter: () => {
        if (cardMesh.userData.hovering) return;
        cardMesh.userData.hovering = true;

        gsap.to(cardGroup.position, {
          y: 0.06,
          z: 0.12,
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });

        glyph.traverse((child) => {
          if (child.isMesh && child.material) {
            gsap.to(child.material, {
              emissiveIntensity: 2.2,
              duration: 0.18,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
            });
          }
        });

        gsap.to(shadowMesh.scale, {
          x: 1.15,
          y: 1.1,
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });

        gsap.to(shadowMesh.material, {
          opacity: 0.65,
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
      },
      mouseleave: () => {
        if (!cardMesh.userData.hovering) return;
        cardMesh.userData.hovering = false;

        gsap.to(cardGroup.position, {
          y: 0,
          z: 0,
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });

        glyph.traverse((child) => {
          if (child.isMesh && child.material) {
            gsap.to(child.material, {
              emissiveIntensity: 1.6,
              duration: 0.18,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
            });
          }
        });

        gsap.to(shadowMesh.scale, {
          x: 1,
          y: 1,
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });

        gsap.to(shadowMesh.material, {
          opacity: 0.5,
          duration: 0.18,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        });
      }
    };

    root.add(cardGroup);
  });

  // Stagger entrance: fade-up opacity 0->1, y +0.2->0
  cardGroups.forEach((cg) => {
    cg.position.y = 0.2;
    cg.traverse((obj) => {
      if (obj.isMesh && obj.material) {
        obj.material.opacity = 0;
      }
    });
  });

  mainTimeline = gsap.timeline();
  cardGroups.forEach((cg, idx) => {
    const delay = idx * 0.08;

    mainTimeline.to(cg.position, {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, delay);

    cg.traverse((obj) => {
      if (obj.isMesh && obj.material) {
        mainTimeline.to(obj.material, {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        }, delay);
      }
    });
  });

  // Lighting: key upper-left, rim opposite
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 1.5, 1.5);
  root.add(keyLight);

  const rimLight = new DirectionalLight(0xff8866, 0.8);
  rimLight.position.set(-1.5, 0.8, -1.5);
  root.add(rimLight);

  // Cleanup
  root.userData.cleanup = () => {
    if (mainTimeline) mainTimeline.kill();
    gsap.globalTimeline.getChildren().forEach((tl) => {
      if (
        tl._targets &&
        tl._targets.some((t) => root.contains(t))
      ) {
        tl.kill();
      }
    });
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material)
          ? obj.material
          : [obj.material];
        mats.forEach((m) => m.dispose());
      }
    });
  };

  return root;
}
